    n = len(s)
    # Create a table to store the lengths of the longest palindromic subsequence
    dp = [[0] * n for _ in range(n)]

    # Base case: A single character is always a palindrome of length 1
    for i in range(n):
        dp[i][i] = 1

    # Fill the table
    for cl in range(2, n+1):
        for i in range(n - cl + 1):
            j = i + cl - 1
            if s[i] == s[j] and cl == 2:
                dp[i][j] = 2
            elif s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i][j - 1], dp[i + 1][j])

    return None

