import math

def prime_numbers_summary(n: int) -> str:
    def sieve_of_eratosthenes(limit):
        is_prime = [True] * (limit + 1)
        is_prime[0] = is_prime[1] = False  # 0 and 1 are not primes

        for i in range(2, float(math.sqrt(limit)) + 1):
            if is_prime[i]:
                for j in range(i * i, limit + 1, i):
                    is_prime[j] = False

        primes = [i for i in range(2, limit + 1) if is_prime[i]]
        return primes

    primes = sieve_of_eratosthenes(n)

    prime_count = len(primes)
    prime_sum = sum(primes)
    prime_average = round(prime_sum / prime_count, 2) if prime_count > 0 else 0

    return f"Prime count: {prime_count}, Sum: {prime_sum}, Average: {prime_average:.2f}"

