def length_of_LIS(prices: List[int]) -> int:
    """
    This function returns the length of the longest increasing subsequence
    of the given list of stock prices 'prices'.
    """
    if not prices:
        return 0

    lis = []
    for price in prices:
        pos = bisect.bisect_left(lis, price)
        if pos < len(lis):
            lis[lis] = price
        else:
            lis.append(price)

    return len(lis)

