def rotate_matrix(matrix):
    """
    Rotates an NxN matrix 90 degrees clockwise in place.

    :param matrix: List[List[int]], the NxN matrix to be rotated
    """
    # First, transpose the matrix
    n = len(matrix)
    for i in range(n):
        for j in range(i, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i - 1][j]

    # Then, reverse each row
    for i in range(n):
        matrix[i].reverse()

