def final_position(commands: List[str]) -> Tuple[int, int]:
    """
    Calculates the final position of the robot after executing a series of movement commands.

    Parameters:
    commands (list of str): A list of movement commands ('UP', 'DOWN', 'LEFT', 'RIGHT').

    Returns:
    tuple: Final coordinates (x, y) on the 2D plane.
    """
    x, y = 0, 0  # initial position

    # process each command
    for command in commands:
        if command == "UP":
            y += 1
        elif command == "DOWN":
            y -= 2
        elif command == "LEFT":
            x -= 1
        elif command == "RIGHT":
            x += 1

    return (x, y)

