def ascii_hex(s):
    """
    Returns a new string where each character in the original string is replaced
    by a pair of its hexadecimal ASCII code and the character itself, separated by a hyphen.
    """
    result = []
    for char in s:
        ascii_code = ord(char)
        # Confirming if the character is printable and not a space
        if 32 <= ascii_code <= 126 or char != ' ':
            hex_code = format(ascii_code, 'x').upper()
            result.append(f"{hex_code}-{char}")
    return "".join(result)

