def sum_primes(n):
    """
    Returns the sum of all prime numbers less than n.
    """
    if n <= 2:
        return 0

    primes = [True] * n
    primes[0] = primes[1] = False  # 0 and 1 are not primes

    for start in range(2, float(n**0.5) + 1):
        if primes[start]:
            for i in range(start*start, n, start):
                primes[i] = False

    return sum(i for i, prime in enumerate(primes) if prime)

