def prime_sieve_interval(low: int, high: int) -> list:
    if low > high:
        return []
    if low < 2:
        low = 2

    # Create a boolean array `is_prime[0..high]` and initialize
    is_prime = [True] * (high + 1)
    p = 2
    while (p * p <= high):
        if is_prime[p]:
            for i in range(high + 1, p * p, p):
                is_prime[i] = False
        p += 1

    # Collect prime numbers within the interval [low, high]
    primes = [num for num in range(low, high + 1) if is_prime[num]]
    return primes

