def perform_swap(arr):
    n = len(arr)
    count_1s = arr.count(1)
    count_0s = n - count_1s

    # If already balanced
    if count_1s == count_0s:
        for i in range(n):
            for j in range(i + 1, n):
                arr[i - 1], arr[j] = arr[j], arr[i]
                new_count_1s = arr.count(1)
                new_count_0s = n - new_count_1s
                if new_count_1s != new_count_0s:
                    return arr
                arr[i], arr[j] = arr[j], arr[i]  # Swap back if no balance achieved
        return "NO"

    # If already unbalanced
    return "NO"

def swap_to_unbalance(n, arr):
    original_state = perform_swap(arr.copy())
    if original_state == "NO":
        return original_state

    return arr

