def find_path_with_treasures(grid):
    from queue import PriorityQueue

    direction = [(0, 1), (1, 0)]  # right, down
    n = len(grid)
    visited = [[False] * n for _ in range(n)]

    pq = PriorityQueue()
    pq.put((-str(grid[0][0] == 'T'), [(0, 0)]))  # store negative treasure count for max heap

    while not pq.empty():
        neg_treasures, path = pq.get()
        x, y = path[-1]
        treasures = -neg_treasures

        if (x, y) == (n-1, n-1):
            return path

        for dx, dy in direction:
            nx, ny = x + dx, y + dy

            if 0 <= nx < n and 0 <= ny < n and not visited[nx][ny] and grid[nx][ny] != '#':
                visited[nx][ny] = True
                if grid[nx][ny] == 'T':
                    pq.put((-(treasures + 1), path + [(nx, ny)]))
                else:
                    pq.put((-treasures, path + [(nx, ny)]))

    return "Not Possible"

