def max_enchantment_points(N, K, enchantment_points):
    # Create a list to store the maximum enchantment points we can get using i fruits.
    # Initialize with -infinity to indicate initially they are not reachable.
    dp = [-float('inf')] * (K + 1)
    dp[0] = 0  # Zero fruits selected means zero enchantment points

    # Iterate through the enchantment points list
    for points in enchantment_points:
        # Iterate from K down to 1 to prevent using the same point more than once.
        for k in range(K + 1, 0, -1):
            if dp[k-1] != -float('inf'):
                dp[k] = max(dp[k], dp[k-1] + points)

    return max(dp)  # The answer is the maximum value in the dp array.

