def can_sort_by_reversing(n, arr):
    sorted_arr = sorted(arr)
    if sorted_arr == arr:
        return "YES"

    # Find the first element where arr and sorted_arr differ
    l = next(i for i in range(n) if arr[i] != sorted_arr[i])
    # Find the last element where arr and sorted_arr differ
    r = next(i for i in range(-1, n-1, -1) if arr[i] != sorted_arr[i])

    # Reverse the subarray arr[l:r+1]
    arr[l:r+1] = arr[l:r+1][::-1]

    if arr == sorted_arr:
        return "YES"
    else:
        return "NO"

