    max_nights = (k // (k + 1)) // 2  # sum of first k integers

    # We need at least k treasures to be stolen over k days:
    if total_treasures < k:
        return "NO"

    # We need that total number of nights we can potentially fulfill is at least k:
    if max_nights <= total_treasures:
        return "YES"
