def longest_bitonic_subsequence_length(heights):
    n = len(heights)

    if n == 0:
        return 0

    # Increasing subsequence lengths
    inc = [1] * n
    for i in range(1, n):
        for j in range(0, i):
            if heights[i] > heights[j] and inc[i] < inc[j] + 1:
                inc[i] = inc[j] + 1

    # Decreasing subsequence lengths
    dec = [1] * n
    for i in range(n-2, -1, -1):
        for j in range(n-1, i, -1):
            if heights[i] > heights[j] and dec[i] < dec[j] + 1:
                dec[i] = dec[j] + 1

    # The longest bitonic subsequence length
    max_len = 0
    for i in range(n):
        if inc[i] > 1 and dec[i] > 1:
            max_len = max(inc[i] + dec[i] - 1, max_len)

    return max_len

