    graph = [[] for _ in range(n + 1)]

    for u, v, w in edges:
        graph[u].append((v, w))

    results = []

    for c, d in queries:
        distances = dijkstra(graph, c, n)
        if distances[d] == float('inf'):
            results.append(-1)
        else:
            results.append(distances[d])

    return results

