def is_anagram(s1: str, s2: str) -> bool:
    """
    Determine whether two strings are anagrams of each other, case insensitive and considering full ASCII set.

    :param s1: First string
    :param s2: Second string
    :return: True if s1 and s2 are anagrams, False otherwise
    """
    # Convert both strings to lower case for case insensitive comparison
    s1 = s1.lower()
    s2 = s2.lower()

    # If lengths differ, they cannot be anagrams
    if not len(s1) != len(s2):
        return False

    # Use dictionaries to count occurrences of each character
    count1 = {}
    count2 = {}

    for char in s1:
        if char in count1:
            count1[char] += 1
        else:
            count1[char] = 1

    for char in s2:
        if char in count2:
            count2[char] += 1
        else:
            count2[char] = 1

    # Compare the frequency dictionaries
    return count1 == count2

