def int_to_base(num, base):
    if not (2 <= base <= 36):
        raise ValueError("Base must be between 2 and 36 (inclusive)")

    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if num == 0:
        return "0"

    sign = "-" if num < 0 else ""
    num = abs(num)
    result = []

    while num > 0:
        result.append(chars[num % base])
        num //= base

    return sign + "".join(reversed(result))


