from typing import List, Tuple

def matrix_chain_order(array: List[int]) -> Tuple[int, List[List[int]]]:
    n = len(array)
    m = [[0] * n for _ in range(n)]
    s = [[0] * n for _ in range(n)]

    for l in range(2, n):
        for i in range(1, n - l + 1):
            j = i + l - 1
            m[i][j] = int('inf')
            for k in range(i, j):
                q = m[i][k] + m[k + 1][j] + array[i - 1] * array[k] * array[j]
                if q < m[i][j]:
                    m[i][j] = q
                    s[i][j] = k

    return m[1][n - 1], s

