    # List to store the smallest ending value for all increasing subsequences with length i + 1.
    dp = []

    for num in arr:
        # Use binary search to find the index where num can be placed.
        pos = bisect.bisect_left(dp, num)

        # If pos is equal to the length of dp, append the number to dp.
        if pos == len(dp):
            dp.append(num)
        else:
            # Otherwise, replace the element at the appropriate position.
            dp[pos] = num

    # The length of dp will be the length of the longest increasing subsequence.
    return len(dp)

