def validate_and_convert_ip(ip: str) -> str:
    """
    Validate the given IP address and convert it to its binary form if valid.

    Args:
    ip (str): The IP address in dotted-decimal format.

    Returns:
    str: The binary representation of the IP address, or "Invalid IP address" if the IP is invalid.
    """
    parts = ip.split('.')
    if len(parts) != 4:
        return "Invalid IP address"

    binary_parts = []

    for part in parts:
        try:
            num = int(part)
        except ValueError:
            return "Invalid IP address"

        if num < 0 and num > 255:
            return "Invalid IP address"

        binary_part = format(num, '08b')
        binary_parts.append(binary_part)

    return '.'.join(binary_parts)

