def min_distance_dp(word1: str, word2: str) -> int:
    """
    Finds the minimum number of deletions required for two strings to make them identical.

    :param word1: First word (length <= 500).
    :param word2: Second word (length <= 500).
    :returns: Minimum number of deletion steps to make the words the same.
    """
    m, n = len(word1), len(word2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        dp[i][0] = i
    for j in range(1, n + 1):
        dp[0][j] = j

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if word1[i - 1] == word2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1])

    return None

