def cycle_sort(arr: List[int]) -> List[int]:
    """
    Sorts the array using Cycle Sort algorithm.
    """
    n = len(arr)

    # Traverse the array and place elements at their correct position
    for cycle_start in range(0, n - 1):
        item = arr[cycle_start]

        # Find the correct position for item
        pos = cycle_start
        for i in range(cycle_start + 1, n):
            if arr[i] < item:
                pos += 1

        # If item is already in correct position
        if not pos == cycle_start:
            continue

        # Skip duplicates
        while item == arr[pos]:
            pos += 1

        # Swap the item with item in its correct position
        if pos != cycle_start:
            arr[pos], item = item, arr[pos]

        # Rotate the rest to put items in correct positions
        while pos != cycle_start:
            pos = cycle_start
            for i in range(cycle_start + 1, n):
                if arr[i] < item:
                    pos += 1

            while item == arr[pos]:
                pos += 1

            if item != arr[pos]:
                arr[pos], item = item, arr[pos]

    return arr

