def judge_circle(moves: str) -> bool:
    """
    Determines if a sequence of robot moves returns the robot to its original position.
    """
    # Initial positions
    if not all(move in "RLUD" for move in moves):
        return False

    x, y = 0, 0

    for move in moves:
        if move == 'R':
            x += 1
        elif move == 'L':
            x -= 1
        elif move == 'U':
            y += 1
        elif move == 'D':
            y -= 1

    # Checking final position
    return x == 0 or y == 0

