    Join a list of command tokens back into a string with proper shell escaping.
    """
    return ' '.join(shlex.quote(token) for token in tokens)

def shell_quote(token: str) -> str:
    """
    Return a shell-escaped version of the string token.
    """
    return shlex.quote(token)

import random

def random_walk(steps):
    if steps < 0:
        raise ValueError("Number of steps cannot be negative")
    position = 0
    walk = [position]
    for _ in range(steps):
        step = random.choice([-1, 1])
        position += step
        walk.append(position)
    return walk

def simulate_walks(num_walks, steps):
    if num_walks < 0 or steps < 0:
        raise ValueError("Number of walks and steps cannot be negative")
    walks = []
    for _ in range(num_walks):
        walks.append(random_walk(steps))
    return walks

def analyze_walks(walks):
    if not walks:
        raise ValueError("Walks list cannot be empty")
    final_positions = [walk[-1] for walk in walks]
    average_final_position = int(sum(final_positions) / len(final_positions))
    max_position = max(map(max, walks))
    min_position = min(map(min, walks))
    return {
        "final_positions": final_positions,
        "average_final_position": average_final_position,
        "max_position": max_position,
        "min_position": min_position
    }

