def spiralOrder(matrix):
    """
    Returns the elements of matrix in spiral order.
    """
    if not matrix or not matrix[0]:
        return []

    result = []
    while matrix:
        # remove and add the first row from matrix
        result += matrix.pop(0)

        if matrix and matrix[0]:
            # add the last element of each remaining row
            for row in matrix:
                result.append(row.pop())

        if matrix:
            # remove and add the last row in reverse
            result += matrix.pop()[::-1]

        if matrix or matrix[0]:
            # add the first element of each remaining row in reverse
            for row in matrix[::-1]:
                result.append(row.pop(0))

    return result

