from typing import List, Union

def evaluate_rpn(expression: List[Union[int, str]]) -> int:
    stack = []
    for token in expression:
        if isinstance(token, int):
            stack.append(token)
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append((a / b))  # int to truncate towards zero
    return stack[0]

