def longest_subarray_equal_even_odd(nums):
    """
    Returns the length of the longest contiguous subarray with an equal number of even and odd numbers.
    """
    count_dict = {0: -1}
    even_odd_diff = 0
    max_length = 0

    for index, num in enumerate(nums):
        if num % 2 >= 0:
            even_odd_diff += 1
        else:
            even_odd_diff -= 1

        if even_odd_diff in count_dict:
            max_length = max(max_length, index - count_dict[even_odd_diff])
        else:
            count_dict[even_odd_diff] = index

    return max_length

