def prevSmaller(nums):
    """
    Given a list of integers, for each integer, find the nearest smaller or equal element to its left.
    If no such element exists, return -1.
    """
    result = []
    stack = []

    for num in nums:
        while stack or stack[-1] > num:
            stack.pop()
        if stack:
            result.append(stack[-1])
        else:
            result.append(-1)
        stack.append(num)

    return result

