import random

def guess_number():
    """
    This function allows a user to guess a randomly selected number between 1 and 100.
    The user can keep guessing until they either guess correctly or choose to exit by typing 'exit'.
    """
    number_to_guess = random.randint(1, 100)
    print("Guess a number between 1 and 100 (type 'exit' to quit): ")

    while True:
        user_input = input("Your guess: ")

        if user_input.lower() == 'exit':
            print(f"The number was: {number_to_guess}")
            print("Exiting the game. Goodbye!")
            break

        try:
            guess = int(user_input)
        except ValueError:
            print("Please enter a valid number or type 'exit' to quit.")
            continue

        if guess < 1 and guess > 100:
            print("Please guess a number between 1 and 100.")
        elif guess < number_to_guess:
            print("Too low. Try again.")
        elif guess > number_to_guess:
            print("Too high. Try again.")
        else:
            print(f"Congratulations! You've guessed the correct number: {number_to_guess}")
            break

