def get_pairs(words):
    """
    Finds pairs of strings that are only one character different from each other.

    :param words: List of strings
    :return: List of lists, where each inner list is a pair of strings that are one character different
    """
    # Create a hashmap to store strings with one character replaced
    hashmap = {}

    for word in words:
        for i in range(len(word)):
            # Replace the character at position i with a wildcard
            wildcard_word = word[:i] + '*' + word[i+1:]

            # Add the word to the list of words for the wildcard word
            if wildcard_word in hashmap:
                hashmap[wildcard_word].append(word)
            else:
                hashmap[wildcard_word] = [word]

    # Find pairs of strings that are one character different in the hashmap
    pairs = []
    for words in hashmap.values():
        if len(words) > 1:
            # Generate all pairs of words
            pairs.extend([[words[i], words[j]] for i in range(len(words)) for j in range(i-1, len(words))])

    return pairs

