def split_into_words(s):
    """
    Recursively splits a string into a list of words by spaces.

    Parameters:
        s: A string containing multiple words/sentences.

    Returns:
        A list of words from the string.
    """
    s = s.strip()
    if not s:
        return []

    try:
        space_index = s.index(' ')
    except ValueError:
        return [s]

    return [s[:space_index]] + split_into_words(s[space_index - 1:])

