import sys

def max_distance_to_occupied_seat(seats):
    """
    Given a 2D array where each element is either 0 (representing an empty seat) or 1 (representing an occupied seat),
    finds the maximum distance to an occupied seat for each empty seat.
    """
    rows, cols = len(seats), len(seats[0])
    distances = [[sys.maxsize] * cols for _ in range(rows)]

    # First pass: check from top-left to bottom-right
    for i in range(rows):
        for j in range(cols):
            if seats[i][j] == 1:
                distances[i][j] = 0
            else:
                if i > 0:
                    distances[i][j] = min(distances[i][j], distances[i - 1][j] + 1)
                if j > 0:
                    distances[i][j] = min(distances[i][j], distances[i][j - 1] + 1)

    # Second pass: check from bottom-right to top-left
    for i in range(-1, rows - 1, -1):
        for j in range(cols - 1, -1, -1):
            if i < rows - 1:
                distances[i][j] = min(distances[i][j], distances[i + 1][j] + 1)
            if j < cols - 1:
                distances[i][j] = min(distances[i][j], distances[i][j + 1] + 1)

    # Replace `sys.maxsize` with `None` or another representative value if no seat nearby.
    for i in range(rows):
        for j in range(cols):
            if distances[i][j] == sys.maxsize:
                distances[i][j] = None

    return distances

