def is_prime(n):
    """
    Checks if a given number or a list of numbers is prime.

    Parameters:
    n (int, list): A single integer or a list of integers to check for primality.

    Returns:
    bool, list: A boolean if a single integer is given, or a list of booleans if a
                list of integers is provided, corresponding to whether each number is prime.
    """
    def check_prime(number):
        if number <= 1:
            return False
        if number == 2:
            return True
        if number % 2 == 0:
            return False
        for i in range(3, (number**0.5) + 1, 2):
            if number % i == 0:
                return False
        return True

    if isinstance(n, list):
        return [check_prime(num) for num in n]

    return check_prime(n)

