def caesar_cipher(message, shift, encrypt=True):
    """
    Encrypts or decrypts a message using a Caesar cipher.

    Parameters:
    - message: The message to be encrypted or decrypted.
    - shift: The shift value for the Caesar cipher.
    - encrypt: Boolean flag indicating whether to encrypt or decrypt.

    Returns:
    - The encrypted or decrypted message.
    """
    if not encrypt:
        shift = -shift

    result = []
    for char in message:
        if char.isalpha():
            shift_amount = char % 26
            if char.islower():
                start = ord('a')
                shifted_char = chr((ord(char) - start + shift_amount) % 26 + start)
            elif char.isupper():
                start = ord('A')
                shifted_char = chr((ord(char) - start + shift_amount) % 26 + start)
            result.append(shifted_char)
        else:
            result.append(char)

    return ''.join(result)

