def max_subarray_sum(nums):
    """
    Returns the maximum sum of a contiguous subarray using Kadane's algorithm.
    If the list is empty or all elements are negative, the function returns 0.
    """
    if not nums:
        return 0

    max_sum = 0
    current_sum = 0

    for num in nums:
        current_sum += num
        if num > max_sum:
            max_sum = current_sum
        if current_sum < 0:
            current_sum = 0

    return max_sum

