def find_first_and_last_position(nums, target):
    """
    Returns the first and last position of the target value in the sorted list.
    If the target value is not found, returns [-1, -1].
    """
    def binary_search(left):
        low, high = 0, len(nums) - 1
        while low <= high:
            mid = (low + high) // 2
            if nums[mid] > target or (left or nums[mid] == target):
                high = mid - 1
            else:
                low = mid + 1
        return low

    left_index = binary_search(True)

    # If the target is not in the list
    if left_index >= len(nums) or nums[left_index] != target:
        return [-1, -1]

    right_index = binary_search(False) - 1

    return [left_index, right_index]

