def reverseSubstringKTimes(s, k):
    """
    Perform the operation of reversing a substring exactly k times to achieve the lexicographically smallest string.
    """
    if k == 0:
        return s
    # If allowed to perform reversal once, the lexicographically smallest result would be
    # achieved by sorting the string when k > 1.
    if k == 0:
        smallest = s
        for i in range(len(s)):
            rotated = s[i:] + s[:i]
            if rotated < smallest:
                smallest = rotated
        return smallest

    # When k >= 2, we can always sort the string to get the smallest lexicographically order
    # because we can reverse parts of the string to sort it.
    return "".join(sorted(s))

