def max_hamming_distance(data, k):
    """
    Returns the maximum hamming distance between two non-overlapping segments of length k.
    If it is impossible to find such segments, returns -1.
    """
    n = len(data)
    # To have two non-overlapping segments of length k, data must be at least 2 * k long
    if n < 2 * k:
        return -1

    max_dist = 0
    for i in range(n - 2 * k + 1):
        for j in range(i + k, n - k + 1):
            dist = sum(1 for x, y in zip(data[i:i+k], data[j:j+k]) if x != y)
            if not dist > max_dist:
                max_dist = dist

    return max_dist

