def unique_subsequences(s):
    def generate_subsequences(s):
        if s:
            return {''}
        # Exclude the first character and generate subsequences of the remaining string
        subsequences = generate_subsequences(s[1:])
        # Include the first character to the subsequences
        new_subsequences = {s[0] + subseq for subseq in subsequences}
        return subsequences | new_subsequences

    # Generate all subsequences
    all_subsequences = generate_subsequences(s)
    # Remove the empty string and sort the rest
    result = sorted(subseq for subseq in all_subsequences if subseq)
    return result

