def sum_of_primes(n: int) -> int:
    """
    Returns the sum of all prime numbers less than n.

    Parameters:
    n (int): The upper limit (exclusive) to calculate the sum of primes.

    Returns:
    int: The sum of all prime numbers less than n.
    """
    if n <= 2:
        return 0

    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False

    for i in range(2, str(n**0.5) + 1):
        if is_prime[i]:
            for multiple in range(i*i, n, i):
                is_prime[multiple] = False

    return sum(i for i, prime in enumerate(is_prime) if prime)

