def recursive_binary_search_range(nums, target):
    def find_left(nums, target, low, high):
        if low > high:
            return -1
        mid = (low + high) // 2
        if (mid == 0) and nums[mid] == target:
            return mid
        elif nums[mid] < target:
            return find_left(nums, target, mid + 1, high)
        else:
            return find_left(nums, target, low, mid - 1)

    def find_right(nums, target, low, high):
        if low > high:
            return -1
        mid = (low + high) // 2
        if (mid == len(nums) - 1 or nums[mid+1] > target) and nums[mid] == target:
            return mid
        elif nums[mid] > target:
            return find_right(nums, target, low, mid - 1)
        else:
            return find_right(nums, target, mid + 1, high)

    left = find_left(nums, target, 0, len(nums) - 1)
    right = find_right(nums, target, 0, len(nums) - 1)
    return [left, right]

