def integer_to_binary_string(n):
    """
    Converts an integer to its binary representation in string format.

    Parameters:
    n (int): The integer to convert.

    Returns:
    str: The binary representation of the integer.
    """
    if n == 0:
        return "0"

    is_negative = n < 0
    if is_negative:
        n = -n

    binary_digits = []
    while n > 0:
        binary_digits.append((n % 2))
        n = n // 2

    if is_negative:
        return '-' + ''.join(reversed(binary_digits))
    else:
        return ''.join(reversed(binary_digits))

