def min_subset_sum_difference(arr):
    total_sum = sum(arr)
    n = len(arr)
    dp = [[False] * (total_sum + 1) for _ in range(n+1)]

    for i in range(n+1):
        dp[i][0] = True

    for i in range(1, n+1):
        for j in range(1, total_sum + 1):
            if arr[i-1] <= j:
                dp[i][j] = dp[i-1][j]
            else:
                dp[i][j] = dp[i-1][j]

    min_diff = float('inf')

    for j in range(total_sum//2, -1, -1):
        if dp[n][j] == True:
            min_diff = total_sum - 2 * j
            break

    return min_diff

