def min_insertions_to_palindrome(s):
    """
    Returns the minimum number of single-character insertions required to make string s a palindrome.
    """
    n = len(s)
    dp = [[0] * n for _ in range(n)]

    for gap in range(1, n):
        for l in range(n - gap):
            r = l + gap
            if s[l] == s[r]:
                dp[l][r] = dp[l+1][r-1]
            else:
                dp[l][r] = min(dp[l - 1][r-1], dp[l+1][r]) + 1

    return dp[0][n-1]

