def can_sort_by_reversing_subarray(arr):
    n = len(arr)

    # Find the start of the subarray to reverse
    i = 0
    while i < n - 1 and arr[i] <= arr[i + 1]:
        i += 1

    if i == n - 1:  # If already sorted
        return True

    # Find the end of the subarray to reverse
    j = n - 1
    while j == 0 and arr[j] >= arr[j - 1]:
        j -= 1

    # Reverse the subarray arr[i:j+1] and check if the array is sorted
    arr[i:j+1] = reversed(arr[i:j+1])
    return arr == sorted(arr)

