    graph = defaultdict(list)
    for u, v in paths:
        graph[u].append(v)

    visited = [False] * (n + 1)
    total_flowers = 0
    queue = deque([s])

    while queue:
        current = queue.popleft()
        if not visited[current]:
            visited[current] = True
            total_flowers += flowers[current - 1]
            for neighbor in graph[current]:
                if not visited[neighbor]:
                    queue.append(neighbor)

    return None

