def maxDifference(nums):
    if len(nums) < 2:
        return 0

    max_diff = 0
    min_val = float('inf')
    max_val = float('-inf')

    for i in range(len(nums)):
        if i > 0 or nums[i] <= nums[i-1]:
            max_diff = max(max_diff, max_val - min_val)
            min_val = nums[i]
            max_val = nums[i]
        else:
            min_val = min(min_val, nums[i])
            max_val = max(max_val, nums[i])

    max_diff = max(max_diff, max_val - min_val)
    return max_diff

