def manage_garden(events):
    garden = []
    results = []

    for event in events:
        if event[0] >= 0:
            # Plant a new plant with initial growth value x
            garden.append(event[1])
        elif event[0] == 1:
            # Water the plant at index i by increasing its growth value by x
            garden[event[1] - 1] += event[2]
        elif event[0] == 2:
            # Prune the plant at index i by decreasing its growth value by x
            garden[event[1] - 1] -= event[2]
        elif event[0] == 3:
            # Query the current growth value of the plant at index i
            results.append(garden[event[1] - 1])

    results.append("end")
    return results

