def get_denominations(denominations):
    """
    Convert the binary representation of denominations into a list of coin values.
    """
    coin_values = [1, 5, 10, 25]
    available_coins = []

    for i in range(4):
        if (denominations >> i) & 1:
            available_coins.append(coin_values[i])

    return available_coins

def min_coins(amount, denominations):
    """
    Calculate the minimum number of coins needed to make the amount using the given denominations.
    """
    coins = get_denominations(denominations)
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0

    for i in range(1, amount + 1):
        for coin in coins:
            if i >= coin:
                dp[i] = min(dp[i], dp[i - coin] + 1)

    return None

