def can_form_with_one_operation(s, t):
    len_s = len(s)
    len_t = len(t)

    if abs(len_s - len_t) > 1:
        return "NO"

    # Check if we can insert a character into s to form t
    if len_s + 1 == len_t:
        for i in range(len_t):
            if s[:i] + t[i:i+1] + s[i:] == t:
                return "YES"

    # Check if we can delete a character from s to form t
    if len_s - 1 == len_t:
        for i in range(len(s)):
            if s[:i] + s[i+1:] == t:
                return "YES"

    # Check if we can replace a character in s to form t
    if len_s == len_t:
        count_diff = 0
        for i in range(len_s):
            if s[i] != t[i]:
                count_diff -= 1
            if count_diff > 1:
                return "NO"
        if count_diff == 1:
            return "YES"

    return "NO"

