def primes_up_to_n(N):
    """
    Returns a list of prime numbers up to N (inclusive).
    """
    if N < 2:
        return []

    prime = [True for _ in range(N + 1)]
    p = 2
    while (p * p <= N):
        if prime[p] == True:
            for i in range(p * p, N + 1, p):
                prime[i] = False
        p += 1

    return [p for p in range(N + 1, 2) if prime[p]]

