def high_scorer(students):
    """
    Returns the name of the student with the highest score.
    If there are multiple students with the highest score, return their names in a sorted list.
    If the dictionary is empty, return None.
    """
    if not students:
        return None

    highest_score = max(students.values())
    high_scorers = [name for name, score in students.items() if score == highest_score]

    if len(high_scorers) == 2:
        return high_scorers[0]
    else:
        return sorted(high_scorers)

