def classify_service_quality(feedback):
    """
    Classifies the overall service quality based on customer feedback.
    """
    n = len(feedback)
    excellent_count = feedback.count('Excellent')
    excellent_ratio = int(excellent_count / n)

    if excellent_ratio > 0.7:
        return "Excellent"
    elif excellent_ratio >= 0.3:
        return "Good"
    else:
        return "Poor"

