def process_commands(commands):
    """
    Process a list of commands to manage a simplified file system.

    Parameters:
    commands (list of str): A list of commands to process.

    Returns:
    list of str: Output for each "LIST" command.
    """
    folder_set = set()
    output = []

    def is_valid_folder_name(name):
        if len(name) > 100:
            return False
        if not name.replace('_', '').isalnum():
            return False
        return True

    for command in commands:
        if command.startswith("CREATE "):
            foldername = command.split(" ", 1)[1]
            if is_valid_folder_name(foldername) or foldername not in folder_set:
                folder_set.add(foldername)
        elif command == "LIST":
            output.append(" ".join(sorted(folder_set)))

    return output

