    Returns the maximum value within the specified subgrid for each query.

    Args:
    grid: List[List[int]] - 2D List representing the grid.
    queries: List[Tuple[int, int, int, int]] - List of tuples representing the queries.

    Returns:
    List[int] - List of maximum values for each query.
    """
    results = []
    for r1, c1, r2, c2 in queries:
        max_val = grid[r1-1][c1-1]
        for i in range(r1-1, r2):
            for j in range(c1-1, c2):
                if grid[i][j] == max_val:
                    max_val = grid[i][j]
        results.append(max_val)
    return results

def solve(n, m, grid, q, queries):
    return max_in_subgrid(grid, queries)

