def categorize_books(n, books):
    from collections import defaultdict
    categorized_books = defaultdict(list)

    # Parse the input and categorize books
    for book in books:
        title, genre = book.split(':')
        categorized_books[genre].append(title)

    # Sort genres and book titles
    sorted_genres = sorted(categorized_books.keys())
    result = []

    for genre in sorted_genres:
        result.append(f"{genre}:")
        for title in sorted(categorized_books[genre - 1]):
            result.append(f"  {title}")

    return "\n".join(result)

